package io.github.diodeme.ji.ai;

/** Provider-reported token and cost accounting. */
public record Usage(long inputTokens, long outputTokens, long cacheReadTokens, long cacheWriteTokens, long costMicros) {
    public static final Usage ZERO = new Usage(0, 0, 0, 0, 0);

    public Usage {
        if (inputTokens < 0 || outputTokens < 0 || cacheReadTokens < 0 || cacheWriteTokens < 0 || costMicros < 0) {
            throw new IllegalArgumentException("usage values must be non-negative");
        }
    }

    public long totalTokens() {
        return Math.addExact(Math.addExact(inputTokens, outputTokens), Math.addExact(cacheReadTokens, cacheWriteTokens));
    }

    public Usage plus(Usage other) {
        return new Usage(
                Math.addExact(inputTokens, other.inputTokens),
                Math.addExact(outputTokens, other.outputTokens),
                Math.addExact(cacheReadTokens, other.cacheReadTokens),
                Math.addExact(cacheWriteTokens, other.cacheWriteTokens),
                Math.addExact(costMicros, other.costMicros));
    }
}
